import { Suspense } from "react";
import { prisma } from "@/lib/prisma";
import AspirasiList from "./AspirasiList";

/**
 * SKELETON UNTUK DAFTAR PESAN (Hanya bagian datanya)
 */
function AspirasiDataSkeleton() {
  return (
    <div className="flex-1 flex flex-col md:flex-row gap-6 min-h-0 animate-pulse">
      {/* Sidebar List Skeleton */}
      <div className="w-full md:w-[420px] flex flex-col gap-4 flex-shrink-0">
         <div className="space-y-4">
            <div className="h-12 w-full bg-slate-200 dark:bg-slate-800 rounded-2xl" />
            <div className="h-10 w-full bg-slate-100 dark:bg-slate-800/50 rounded-2xl" />
         </div>
         <div className="space-y-3">
            {[1, 2, 3, 4].map((i) => (
               <div key={i} className="h-24 w-full bg-white dark:bg-white/5 border border-slate-100 dark:border-white/5 rounded-2xl p-4 flex flex-col gap-3">
                  <div className="flex justify-between items-start">
                     <div className="flex items-center gap-2">
                        <div className="w-8 h-8 rounded-full bg-slate-200 dark:bg-slate-800" />
                        <div className="h-3 w-20 bg-slate-200 dark:bg-slate-800 rounded" />
                     </div>
                     <div className="h-2 w-10 bg-slate-100 dark:bg-slate-800/50 rounded" />
                  </div>
                  <div className="space-y-2">
                     <div className="h-2 w-full bg-slate-100 dark:bg-slate-800/50 rounded" />
                     <div className="h-2 w-2/3 bg-slate-100 dark:bg-slate-800/50 rounded" />
                  </div>
               </div>
            ))}
         </div>
      </div>

      {/* Detail Area Skeleton */}
      <div className="hidden md:flex flex-1 bg-white dark:bg-[#0f172a]/60 border border-slate-200 dark:border-white/10 rounded-[2.5rem] flex flex-col p-8 space-y-8">
         <div className="flex justify-between items-start mb-6">
            <div className="flex items-center gap-4">
               <div className="w-14 h-14 rounded-2xl bg-slate-200 dark:bg-slate-800" />
               <div className="space-y-2">
                  <div className="h-5 w-40 bg-slate-200 dark:bg-slate-800 rounded" />
                  <div className="h-3 w-24 bg-slate-100 dark:bg-slate-800/50 rounded" />
               </div>
            </div>
            <div className="h-12 w-12 bg-slate-200 dark:bg-slate-800 rounded-2xl" />
         </div>
         <div className="flex gap-3">
            <div className="h-8 w-24 bg-slate-100 dark:bg-slate-800/50 rounded-xl" />
            <div className="h-8 w-32 bg-slate-100 dark:bg-slate-800/50 rounded-xl" />
            <div className="h-8 w-28 bg-slate-100 dark:bg-slate-800/50 rounded-xl" />
         </div>
         <div className="h-40 w-full bg-slate-50 dark:bg-white/5 rounded-[2rem] border border-slate-100 dark:border-white/5" />
         <div className="space-y-4 pt-8 border-t border-slate-100 dark:border-white/5">
            <div className="h-4 w-32 bg-slate-200 dark:bg-slate-800 rounded" />
            <div className="h-32 w-full bg-slate-50 dark:bg-white/5 rounded-3xl" />
         </div>
      </div>
    </div>
  );
}

/**
 * KOMPONEN SERVER (Mengambil data asli)
 */
async function AspirasiTableData() {
  const data = await prisma.aspirasi.findMany({
    orderBy: { createdAt: 'desc' }
  });

  return <AspirasiList initialData={data} />;
}

export default async function InboxPage() {
  return (
    <div className="h-[calc(100vh-140px)] flex flex-col font-sans relative overflow-hidden">
      
      {/* JUDUL STATIS (Agar tidak duplikat dengan AspirasiList) */}
      <div className="flex-shrink-0 mb-6">
          <div className="flex items-center gap-3">
             <h1 className="text-3xl font-black font-bold text-slate-900 dark:text-white tracking-tight flex items-center gap-3">
               Inbox Aspirasi <span className="text-2xl p-2 bg-pink-100 dark:bg-pink-900/30 rounded-full">📩</span>
             </h1>
          </div>
          <p className="text-slate-500 dark:text-slate-400 text-sm font-medium mt-1 ml-1">
            Respon aspirasi dan keluhan siswa secara profesional.
          </p>
      </div>

      <Suspense fallback={<AspirasiDataSkeleton />}>
         <AspirasiTableData />
      </Suspense>
    </div>
  );
}
